<div class="page-heading"><div><h1><?=e($title)?><span class="heading-dot">.</span></h1><p>Arsip hanya baca. Nilai ditampilkan sesuai ekspor database sumber.</p></div><a href="<?=e(url('migrasi'))?>" class="btn btn-light">Kembali ke migrasi</a></div><section class="surface"><div class="panel-header"><h2><?=e($metadata['table_name'])?></h2><span class="soft-badge"><?=e($metadata['row_count'])?> baris</span></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Urutan sumber</th><th>Data asli</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['source_ordinal'])?></td><td><pre class="archive-json"><?=e(json_encode(json_decode($row['payload'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="2" class="table-empty">Tabel sumber tidak memiliki baris aktif.</td></tr><?php endif;?></tbody></table></div><div class="table-pagination"><span>Halaman <?=$page?></span><div><?php if($page>1):?><a class="btn btn-light btn-sm" href="<?=url('arsip',['table'=>$metadata['table_name'],'page'=>$page-1])?>">Sebelumnya</a><?php endif;?><?php if($page*25<(int)$metadata['row_count']):?><a class="btn btn-light btn-sm" href="<?=url('arsip',['table'=>$metadata['table_name'],'page'=>$page+1])?>">Berikutnya</a><?php endif;?></div></div></section>
